files.code:
* { box-sizing: border-box; }
body { margin: 0; font-family: system-ui, sans-serif; color: #0b2540; }
a { text-decoration: none; }
:root { --brand: #0b6fd6; --accent: #0aa5b8; }

.nav {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 16px 24px;
}
.logo { font-weight: 800; font-size: 1.4rem; color: var(--brand); }
.logo span { color: var(--accent); }
.nav nav a { margin-left: 16px; color: inherit; }

.hero {
  text-align: center;
  padding: 64px 24px;
  background: linear-gradient(135deg, var(--brand), var(--accent));
  color: white;
}
.hero h1 { font-size: clamp(1.8rem, 5vw, 3rem); margin: 0 0 12px; }
.cta {
  display: inline-block;
  margin-top: 16px;
  padding: 12px 24px;
  background: white;
  color: var(--brand);
  border-radius: 999px;
  font-weight: 700;
  transition: transform 0.2s;
}
.cta:hover { transform: translateY(-2px) scale(1.04); }

.features {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
  padding: 32px 24px;
}
.card {
  padding: 20px;
  border-radius: 12px;
  box-shadow: 0 4px 16px rgba(11, 111, 214, 0.15);
}

@media (max-width: 600px) {
  .features { grid-template-columns: 1fr; }
  .nav { flex-direction: column; gap: 8px; }
}

